def save_project(path=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0488000" if __import__("os").path.isdir("./environment_mix/0488000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()

    instances = _load("qgis_instances.json")
    projects = _load("projects.json")
    layers = _load("layers.json")
    operations = _load("operations.json")

    def _log_op(instance_id, project_id, layer_id, op_status, request_obj, result_obj=None, artifact_path=None, error_message=None):
        now = _now()
        op = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "project_id": project_id,
            "layer_id": layer_id,
            "op_type": "save_project",
            "status": op_status,
            "request": request_obj if isinstance(request_obj, dict) else {},
            "result": result_obj,
            "artifact_path": artifact_path,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        operations.append(op)
        _save("operations.json", operations)
        return op

    # Validate input
    if path is not None and not isinstance(path, str):
        # still log if possible
        # choose any usable ready/degraded instance for audit context
        inst = next((i for i in instances if i.get("status") in ("ready", "degraded")), None)
        inst_id = inst.get("id") if inst else None
        _log_op(inst_id or "unknown", None, None, "failed", {"path": path}, None, None, "Invalid path type; expected string or null")
        return _err("VALIDATION_ERROR", "path must be a string or null")
    if isinstance(path, str):
        if path.strip() == "":
            inst = next((i for i in instances if i.get("status") in ("ready", "degraded")), None)
            inst_id = inst.get("id") if inst else None
            _log_op(inst_id or "unknown", None, None, "failed", {"path": path}, None, None, "Path must not be empty")
            return _err("VALIDATION_ERROR", "path must not be empty")
        if len(path) > 2048:
            inst = next((i for i in instances if i.get("status") in ("ready", "degraded")), None)
            inst_id = inst.get("id") if inst else None
            _log_op(inst_id or "unknown", None, None, "failed", {"path": path}, None, None, "Path too long")
            return _err("VALIDATION_ERROR", "path is too long", limit=2048)

    # Resolve an active engine context: instance ready/degraded with an active/dirty/saving project
    # Prefer "active"/"dirty" project
    candidate = None
    candidate_instance = None
    for inst in instances:
        if inst.get("status") not in ("ready", "degraded"):
            continue
        inst_id = inst.get("id")
        inst_projects = [p for p in projects if p.get("instance_id") == inst_id and p.get("status") in ("active", "dirty", "saving")]
        # choose active/dirty first
        inst_projects.sort(key=lambda p: {"active": 0, "dirty": 1, "saving": 2}.get(p.get("status"), 9))
        if inst_projects:
            candidate = inst_projects[0]
            candidate_instance = inst
            break

    if candidate_instance is None:
        # No viable engine context anywhere in store
        # record operation (best-effort, with unknown instance)
        _log_op("unknown", None, None, "failed", {"path": path}, None, None, "No active QGIS engine context available")
        return _err("UNAUTHORIZED", "No active QGIS engine context available")

    project = candidate
    inst = candidate_instance
    inst_id = inst.get("id")
    proj_id = project.get("id")

    # Determine resolved save path
    resolved_path = path if isinstance(path, str) else project.get("file_path")

    if resolved_path is None:
        # Must fail: first save requires a path
        _log_op(inst_id, proj_id, None, "failed", {"path": path}, None, None, "A path is required for first save when project.file_path is null")
        return _err("CONFLICT", "A path is required for first save when the project has no existing file_path")

    if not isinstance(resolved_path, str) or resolved_path.strip() == "":
        _log_op(inst_id, proj_id, None, "failed", {"path": path}, None, None, "Resolved save path is invalid")
        return _err("VALIDATION_ERROR", "Resolved save path is invalid")

    # Enforce unique(instance_id, file_path) WHERE file_path IS NOT NULL
    for p in projects:
        if p.get("id") != proj_id and p.get("instance_id") == inst_id and p.get("file_path") is not None and p.get("file_path") == resolved_path:
            _log_op(inst_id, proj_id, None, "failed", {"path": path}, None, None, "Another project already exists with the same (instance_id, file_path)")
            return _err("CONFLICT", "Another project already exists for this instance with the same file_path")

    # Lifecycle transitions: project status -> saving is allowed from active/dirty, also from error per schema? (error allows closed/active only)
    # If project currently saving, allow idempotent save.
    from_status = project.get("status")
    allowed = {
        "active": {"dirty", "saving", "closed", "error"},
        "dirty": {"saving", "closed", "error", "active"},
        "saving": {"active", "dirty", "error"},
        "error": {"closed", "active"},
        "closed": set(),
    }
    now = _now()

    # Move to saving if not already saving
    if from_status != "saving":
        if "saving" not in allowed.get(from_status, set()):
            _log_op(inst_id, proj_id, None, "failed", {"path": path}, None, None, f"Invalid project status transition {from_status} -> saving")
            return _err("INVALID_TRANSITION", f"Cannot transition project status from {from_status} to saving")
        project["status"] = "saving"
        project["updated_at"] = now
        # persist intermediate transition
        _save("projects.json", projects)

    # Perform "save" side-effects: update file_path if path provided, last_saved_at, updated_at; then set status to active
    if isinstance(path, str):
        project["file_path"] = resolved_path
    project["last_saved_at"] = now
    project["updated_at"] = now

    # Return to active after saving (legal from saving)
    if "active" not in allowed.get("saving", set()):
        _log_op(inst_id, proj_id, None, "failed", {"path": path}, None, None, "Invalid project status transition saving -> active")
        return _err("INVALID_TRANSITION", "Cannot transition project status from saving to active")
    project["status"] = "active"
    project["updated_at"] = now
    _save("projects.json", projects)

    # Log succeeded operation
    op = _log_op(inst_id, proj_id, None, "succeeded", {"path": path}, {"saved_path": resolved_path, "project_id": proj_id}, artifact_path=resolved_path, error_message=None)

    return {
        "saved_path": resolved_path,
        "project": project,
        "operation": op,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def get_operations(instance_id=None, project_id=None, layer_id=None, op_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0488000" if __import__("os").path.isdir("./environment_mix/0488000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_iso(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    instances = _load("qgis_instances.json")
    projects = _load("projects.json")
    layers = _load("layers.json")
    operations = _load("operations.json")

    # Validate filters
    if instance_id is not None and not isinstance(instance_id, str):
        return _err("VALIDATION_ERROR", "instance_id must be a string or null")
    if project_id is not None and not isinstance(project_id, str):
        return _err("VALIDATION_ERROR", "project_id must be a string or null")
    if layer_id is not None and not isinstance(layer_id, str):
        return _err("VALIDATION_ERROR", "layer_id must be a string or null")
    valid_op_types = {None, "ping", "get_qgis_info", "load_project", "create_new_project", "save_project", "close_project",
                      "add_vector_layer", "add_raster_layer", "remove_layer", "zoom_to_layer", "get_layer_features",
                      "execute_processing", "render_map", "execute_code"}
    if op_type not in valid_op_types:
        return _err("VALIDATION_ERROR", "Invalid op_type")
    valid_status = {None, "queued", "running", "succeeded", "failed", "cancelled"}
    if status not in valid_status:
        return _err("VALIDATION_ERROR", "Invalid status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string or null")

    # Reference existence checks when supplied (per tool description)
    if instance_id is not None:
        if not any(i.get("id") == instance_id for i in instances):
            return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    if project_id is not None:
        if not any(p.get("id") == project_id for p in projects):
            return _err("NOT_FOUND", "Project not found", project_id=project_id)
    if layer_id is not None:
        if not any(l.get("id") == layer_id for l in layers):
            return _err("NOT_FOUND", "Layer not found", layer_id=layer_id)

    # Ambient auth: allow if there exists at least one instance (system has logs); otherwise unauthorized
    if not instances and not operations:
        return _err("UNAUTHORIZED", "No accessible log context available")

    # Filter
    filtered = operations[:]
    if instance_id is not None:
        filtered = [o for o in filtered if o.get("instance_id") == instance_id]
    if project_id is not None:
        filtered = [o for o in filtered if o.get("project_id") == project_id]
    if layer_id is not None:
        filtered = [o for o in filtered if o.get("layer_id") == layer_id]
    if op_type is not None:
        filtered = [o for o in filtered if o.get("op_type") == op_type]
    if status is not None:
        filtered = [o for o in filtered if o.get("status") == status]

    # Sort reverse chronological by created_at then id
    def _sort_key(o):
        dt = _parse_iso(o.get("created_at")) or datetime.datetime.min
        return (dt, o.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    # Cursor pagination: cursor is the last seen operation id in this sorted order
    start_index = 0
    if cursor:
        idx = next((i for i, o in enumerate(filtered) if o.get("id") == cursor), None)
        if idx is not None:
            start_index = idx + 1
        else:
            # Unknown cursor: treat as empty page rather than error (common API behavior)
            start_index = len(filtered)

    page = filtered[start_index:start_index + limit]
    has_more = start_index + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    # Observable dynamics: record this read as an audit operation row (op_type isn't defined for get_operations,
    # so we record as get_qgis_info (closest "read/info") with request payload to preserve auditability.
    # This adheres to schema constraints (op_type enum) and doesn't fabricate non-schema op_types.
    now = _iso_now()
    # pick a context instance if possible
    ctx_inst_id = instance_id
    if ctx_inst_id is None:
        ctx_inst = next((i for i in instances if i.get("status") in ("ready", "degraded", "starting", "stopped")), None)
        ctx_inst_id = ctx_inst.get("id") if ctx_inst else (page[0].get("instance_id") if page else "unknown")
    ctx_proj_id = project_id
    if ctx_proj_id is None and page:
        ctx_proj_id = page[0].get("project_id")

    read_op = {
        "id": f"op_{int(time.time()*1000)}_{os.getpid()}",
        "instance_id": ctx_inst_id,
        "project_id": ctx_proj_id,
        "layer_id": layer_id if layer_id is not None else (page[0].get("layer_id") if page else None),
        "op_type": "get_qgis_info",
        "status": "succeeded",
        "request": {
            "tool": "get_operations",
            "filters": {"instance_id": instance_id, "project_id": project_id, "layer_id": layer_id, "op_type": op_type, "status": status},
            "limit": limit,
            "cursor": cursor,
        },
        "result": {"returned": len(page)},
        "artifact_path": None,
        "error_message": None,
        "started_at": now,
        "finished_at": now,
        "created_at": now,
        "updated_at": now,
    }
    operations.append(read_op)
    _save("operations.json", operations)

    return {
        "operations": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }
